ImagePatch.prototype.distance_to_camera = function() {
    // Assuming the center of the image is considered the camera
    const centerX = this.width / 2;
    const centerY = this.height / 2;
    const zebraCenterX = this.left + (this.right - this.left) / 2;
    const zebraCenterY = this.lower + (this.upper - this.lower) / 2;
    return Math.sqrt((centerX - zebraCenterX) ** 2 + (centerY - zebraCenterY) ** 2);
}

